create extension if not exists "pgcrypto";

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default 'Rasoi friend', avatar_url text, created_at timestamptz not null default now());
alter table public.profiles drop column if exists account_type;
create table public.recipes (
  id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete cascade,
  title text not null check (char_length(title) between 3 and 120), category text not null check (category in ('Breakfast','Sabzi','Dal & Rice','Roti & Paratha','Snacks','Non-Veg','Sweets','Drinks')),
  is_veg boolean not null default true, is_hostel_friendly boolean not null default false, cooking_time integer not null check (cooking_time between 1 and 1440), servings integer not null check (servings between 1 and 50), image_url text not null,
  ingredients jsonb not null check (jsonb_typeof(ingredients) = 'array'), steps jsonb not null check (jsonb_typeof(steps) = 'array'), description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.ratings (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rating integer not null check (rating between 1 and 5), created_at timestamptz not null default now(), unique(user_id, recipe_id));
create table public.favourites (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(user_id, recipe_id));
create table public.comments (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, body text not null check (char_length(body) between 1 and 1000), created_at timestamptz not null default now());
alter table public.recipes add column if not exists is_hostel_friendly boolean not null default false;

create index recipes_category_idx on public.recipes(category); create index recipes_author_idx on public.recipes(author_id); create index recipes_time_idx on public.recipes(cooking_time); create index recipes_created_idx on public.recipes(created_at desc); create index ratings_recipe_idx on public.ratings(recipe_id); create index comments_recipe_idx on public.comments(recipe_id, created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name, account_type) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', 'Rasoi friend'), case when new.raw_user_meta_data ->> 'account_type' = 'creator' then 'creator' else 'reader' end); return new; end; $$;
create or replace trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

alter table public.profiles enable row level security; alter table public.recipes enable row level security; alter table public.ratings enable row level security; alter table public.favourites enable row level security; alter table public.comments enable row level security;
create policy "profiles are public" on public.profiles for select using (true); create policy "users update own profile" on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);
create policy "recipes are public" on public.recipes for select using (true); create policy "signed in users create recipes" on public.recipes for insert to authenticated with check (auth.uid() = author_id); create policy "owners update recipes" on public.recipes for update using (auth.uid() = author_id) with check (auth.uid() = author_id); create policy "owners delete recipes" on public.recipes for delete using (auth.uid() = author_id);
create policy "ratings are public" on public.ratings for select using (true); create policy "signed in users rate" on public.ratings for insert to authenticated with check (auth.uid() = user_id); create policy "users change own rating" on public.ratings for update using (auth.uid() = user_id) with check (auth.uid() = user_id); create policy "users remove own rating" on public.ratings for delete using (auth.uid() = user_id);
create policy "favourites are public" on public.favourites for select using (true); create policy "users save recipes" on public.favourites for insert to authenticated with check (auth.uid() = user_id); create policy "users unsave recipes" on public.favourites for delete using (auth.uid() = user_id);
create policy "comments are public" on public.comments for select using (true); create policy "signed in users comment" on public.comments for insert to authenticated with check (auth.uid() = user_id); create policy "authors delete own comments" on public.comments for delete using (auth.uid() = user_id);

insert into storage.buckets (id, name, public) values ('recipe-images', 'recipe-images', true) on conflict (id) do update set public = true;
create policy "recipe images are public" on storage.objects for select using (bucket_id = 'recipe-images'); create policy "users upload recipe images" on storage.objects for insert to authenticated with check (bucket_id = 'recipe-images' and (storage.foldername(name))[1] = auth.uid()::text); create policy "users update recipe images" on storage.objects for update to authenticated using (bucket_id = 'recipe-images' and owner_id = auth.uid()::text); create policy "users delete recipe images" on storage.objects for delete to authenticated using (bucket_id = 'recipe-images' and owner_id = auth.uid()::text);